import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const JobSeekerDashboard: React.FC = () => {
    const navigate = useNavigate();
    const [agencyDetails, setAgencyDetails] = useState<any>(null);
    const [jobSeeker, setJobSeeker] = useState<any>(null);
    const [status, setStatus] = useState<string>('pending');

    useEffect(() => {
        const token = localStorage.getItem('token');
        const agency = localStorage.getItem('agencyDetails');
        const firstName = localStorage.getItem('firstName'); 

        if (!token) {
            navigate('/login'); 
        }

        if (agency) {
            const parsedAgency = JSON.parse(agency);
            setAgencyDetails(parsedAgency);
        }

        // if (jobSeekerData) {
        //     try {
        //         const parsedJobSeeker = JSON.parse(jobSeekerData);
        //         setJobSeeker(parsedJobSeeker);
        //         setStatus(parsedJobSeeker.status);
        //     } catch (error) {
        //         console.error('Error parsing job seeker data:', error);
        //     }
        // } else {
        //     console.log('No job seeker found in localStorage.');
        // }
    }, [navigate]);

    const handleChatClick = (userId: number, agencyId: number) => {
        navigate(`/chat/${userId}/${agencyId}`); 
    };

    return (
        <div className="container mt-5">
            <h1 className="text-center">Job Seeker Dashboard</h1>
            {jobSeeker && (
                <div className="alert alert-info">
                    <h4>Welcome, {jobSeeker.firstName} {jobSeeker.lastName}!</h4>
                </div>
            )}
            <div className="card p-4 mt-3">
                <h2>Your Agency Details</h2>
                {agencyDetails ? (
                    <div>
                        <p><strong>Agency Name:</strong> {agencyDetails.firstName} {agencyDetails.lastName}</p>
                        <p><strong>Email:</strong> {agencyDetails.email}</p>
                        <p><strong>Phone:</strong> {agencyDetails.phone}</p>
                        {status === 'confirmed' ? ( 
                            <>
                                <button onClick={() => handleChatClick(jobSeeker.id, jobSeeker.agencyId)} className="btn btn-primary mt-3">
                                    Start Chat
                                </button>
                                <div className="alert alert-success mt-3">
                                    You have been confirmed by your agency. You can start chatting now!
                                </div>
                            </>
                        ) : (
                            <p className="text-danger mt-3">Your agency has not confirmed you for chat.</p>
                        )}
                    </div>
                ) : (
                    <p>No agency associated with your profile.</p>
                )}
            </div>
        </div>
    );
};

export default JobSeekerDashboard;
